-- MavenMovies-style large PostgreSQL practice database for HeidiSQL
-- 1,500+ generated data rows across related tables
-- PostgreSQL syntax
DROP SCHEMA IF EXISTS mavenmovies CASCADE;
CREATE SCHEMA mavenmovies;
SET search_path TO mavenmovies;

CREATE TABLE language (
 language_id SERIAL PRIMARY KEY,
 name VARCHAR(30) NOT NULL,
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE country (
 country_id SERIAL PRIMARY KEY,
 country VARCHAR(60) NOT NULL,
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE city (
 city_id SERIAL PRIMARY KEY,
 city VARCHAR(60) NOT NULL,
 country_id INT NOT NULL REFERENCES country(country_id),
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE address (
 address_id SERIAL PRIMARY KEY,
 address VARCHAR(120) NOT NULL,
 address2 VARCHAR(120),
 district VARCHAR(60),
 city_id INT NOT NULL REFERENCES city(city_id),
 postal_code VARCHAR(20),
 phone VARCHAR(25),
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE store (
 store_id SERIAL PRIMARY KEY,
 manager_staff_id INT,
 address_id INT NOT NULL REFERENCES address(address_id),
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE staff (
 staff_id SERIAL PRIMARY KEY,
 first_name VARCHAR(45) NOT NULL,
 last_name VARCHAR(45) NOT NULL,
 address_id INT NOT NULL REFERENCES address(address_id),
 email VARCHAR(100),
 store_id INT NOT NULL REFERENCES store(store_id),
 active BOOLEAN DEFAULT TRUE,
 username VARCHAR(40) NOT NULL,
 password VARCHAR(100),
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE customer (
 customer_id SERIAL PRIMARY KEY,
 store_id INT NOT NULL REFERENCES store(store_id),
 first_name VARCHAR(45) NOT NULL,
 last_name VARCHAR(45) NOT NULL,
 email VARCHAR(100),
 address_id INT NOT NULL REFERENCES address(address_id),
 active BOOLEAN DEFAULT TRUE,
 create_date DATE DEFAULT CURRENT_DATE,
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE film (
 film_id SERIAL PRIMARY KEY,
 title VARCHAR(255) NOT NULL,
 description TEXT,
 release_year INT,
 language_id INT NOT NULL REFERENCES language(language_id),
 rental_duration INT NOT NULL,
 rental_rate NUMERIC(5,2) NOT NULL,
 length INT,
 replacement_cost NUMERIC(6,2) NOT NULL,
 rating VARCHAR(10),
 special_features TEXT,
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE actor (
 actor_id SERIAL PRIMARY KEY,
 first_name VARCHAR(45) NOT NULL,
 last_name VARCHAR(45) NOT NULL,
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE category (
 category_id SERIAL PRIMARY KEY,
 name VARCHAR(30) NOT NULL,
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE film_actor (
 actor_id INT NOT NULL REFERENCES actor(actor_id),
 film_id INT NOT NULL REFERENCES film(film_id),
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(actor_id,film_id)
);
CREATE TABLE film_category (
 film_id INT NOT NULL REFERENCES film(film_id),
 category_id INT NOT NULL REFERENCES category(category_id),
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(film_id,category_id)
);
CREATE TABLE inventory (
 inventory_id SERIAL PRIMARY KEY,
 film_id INT NOT NULL REFERENCES film(film_id),
 store_id INT NOT NULL REFERENCES store(store_id),
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE rental (
 rental_id SERIAL PRIMARY KEY,
 rental_date TIMESTAMP NOT NULL,
 inventory_id INT NOT NULL REFERENCES inventory(inventory_id),
 customer_id INT NOT NULL REFERENCES customer(customer_id),
 return_date TIMESTAMP,
 staff_id INT NOT NULL REFERENCES staff(staff_id),
 last_update TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE payment (
 payment_id SERIAL PRIMARY KEY,
 customer_id INT NOT NULL REFERENCES customer(customer_id),
 staff_id INT NOT NULL REFERENCES staff(staff_id),
 rental_id INT REFERENCES rental(rental_id),
 amount NUMERIC(7,2) NOT NULL,
 payment_date TIMESTAMP NOT NULL
);


UPDATE store SET manager_staff_id=1 WHERE store_id=1;
