-- Helpful indexes
CREATE INDEX idx_film_language ON film(language_id);
CREATE INDEX idx_film_actor_film ON film_actor(film_id);
CREATE INDEX idx_film_actor_actor ON film_actor(actor_id);
CREATE INDEX idx_film_category_film ON film_category(film_id);
CREATE INDEX idx_film_category_category ON film_category(category_id);
CREATE INDEX idx_inventory_film ON inventory(film_id);
CREATE INDEX idx_inventory_store ON inventory(store_id);
CREATE INDEX idx_rental_inventory ON rental(inventory_id);
CREATE INDEX idx_rental_customer ON rental(customer_id);
CREATE INDEX idx_payment_customer ON payment(customer_id);
CREATE INDEX idx_payment_rental ON payment(rental_id);
ANALYZE;

-- Row-count check
SELECT 'language' table_name, COUNT(*) row_count FROM language
UNION ALL SELECT 'country',COUNT(*) FROM country
UNION ALL SELECT 'city',COUNT(*) FROM city
UNION ALL SELECT 'address',COUNT(*) FROM address
UNION ALL SELECT 'store',COUNT(*) FROM store
UNION ALL SELECT 'staff',COUNT(*) FROM staff
UNION ALL SELECT 'customer',COUNT(*) FROM customer
UNION ALL SELECT 'film',COUNT(*) FROM film
UNION ALL SELECT 'actor',COUNT(*) FROM actor
UNION ALL SELECT 'category',COUNT(*) FROM category
UNION ALL SELECT 'film_actor',COUNT(*) FROM film_actor
UNION ALL SELECT 'film_category',COUNT(*) FROM film_category
UNION ALL SELECT 'inventory',COUNT(*) FROM inventory
UNION ALL SELECT 'rental',COUNT(*) FROM rental
UNION ALL SELECT 'payment',COUNT(*) FROM payment
ORDER BY table_name;

-- ============================================
-- JOIN PRACTICE QUERIES
-- ============================================
-- Practice 1
SELECT f.title,l.name AS language
FROM film f JOIN language l ON f.language_id=l.language_id;

-- Practice 2
SELECT f.title,c.name AS category
FROM film f JOIN film_category fc ON f.film_id=fc.film_id
JOIN category c ON fc.category_id=c.category_id
ORDER BY f.title;

-- Practice 3
SELECT f.title,a.first_name,a.last_name
FROM film f JOIN film_actor fa ON f.film_id=fa.film_id
JOIN actor a ON fa.actor_id=a.actor_id;

-- Practice 4
SELECT c.first_name,c.last_name,COUNT(r.rental_id) AS rentals
FROM customer c LEFT JOIN rental r ON c.customer_id=r.customer_id
GROUP BY c.customer_id,c.first_name,c.last_name
ORDER BY rentals DESC;

-- Practice 5
SELECT f.title,COUNT(r.rental_id) AS rentals,SUM(p.amount) AS revenue
FROM film f JOIN inventory i ON f.film_id=i.film_id
JOIN rental r ON i.inventory_id=r.inventory_id
JOIN payment p ON r.rental_id=p.rental_id
GROUP BY f.film_id,f.title ORDER BY revenue DESC LIMIT 20;

-- Practice 6
SELECT ci.city,co.country,COUNT(c.customer_id) AS customers
FROM customer c JOIN address ad ON c.address_id=ad.address_id
JOIN city ci ON ad.city_id=ci.city_id
JOIN country co ON ci.country_id=co.country_id
GROUP BY ci.city,co.country ORDER BY customers DESC;

-- Practice 7
SELECT c.name,COUNT(fc.film_id) AS film_count
FROM category c LEFT JOIN film_category fc ON c.category_id=fc.category_id
GROUP BY c.category_id,c.name ORDER BY film_count DESC;

-- Practice 8
SELECT l.name,ROUND(AVG(f.rental_rate),2) AS avg_rate
FROM language l JOIN film f ON l.language_id=f.language_id
GROUP BY l.language_id,l.name ORDER BY avg_rate DESC;

-- Practice 9
SELECT s.store_id,COUNT(r.rental_id) AS rentals,SUM(p.amount) AS revenue
FROM store s JOIN inventory i ON s.store_id=i.store_id
JOIN rental r ON i.inventory_id=r.inventory_id
JOIN payment p ON r.rental_id=p.rental_id
GROUP BY s.store_id ORDER BY revenue DESC;

-- Practice 10
SELECT a.first_name,a.last_name,COUNT(fa.film_id) AS film_count
FROM actor a LEFT JOIN film_actor fa ON a.actor_id=fa.actor_id
GROUP BY a.actor_id,a.first_name,a.last_name
HAVING COUNT(fa.film_id)>5 ORDER BY film_count DESC;

-- Practice 11
SELECT c.first_name,c.last_name,SUM(p.amount) AS total_spent
FROM customer c JOIN payment p ON c.customer_id=p.customer_id
GROUP BY c.customer_id,c.first_name,c.last_name
HAVING SUM(p.amount)>20 ORDER BY total_spent DESC;

-- Practice 12
SELECT title,length FROM film
WHERE length>(SELECT AVG(length) FROM film)
ORDER BY length DESC;
